const ROOM = 'broadcast';
const PEER_ID = crypto.randomUUID();
const peers = new Map(); // peerId → { pc, stream, pendingIce, makingOffer }
const isPolite = (id) => PEER_ID < id;

const ws = new WebSocket('wss://' + location.host + '/ws');
ws.onopen = () => {
  ws.send(JSON.stringify({ type:'join', room:ROOM }));
  bcast({ kind:'hello', from:PEER_ID });
};
ws.onmessage = async ev => {
  const m = JSON.parse(ev.data);
  const p = m.payload;  if (!p || p.from === PEER_ID) return;
  if (p.kind === 'hello') return initiatePeer(p.from);
  if (p.to !== PEER_ID) return;
  const peer = peers.get(p.from);
  if (p.kind === 'offer')  await handleOffer(p, peer);
  if (p.kind === 'answer') { await peer.pc.setRemoteDescription(p.sdp); await flushIce(peer); }
  if (p.kind === 'ice')    await addIce(peer, p.candidate);
};
function bcast(payload) { ws.send(JSON.stringify({ type:'broadcast', room:ROOM, payload })); }

async function initiatePeer(peerId) {
  const peer = makePeer(peerId);
  if (localStream) localStream.getTracks().forEach(t => peer.pc.addTrack(t, localStream));
  // onnegotiationneeded fires automatically and calls renegotiate().
}
async function renegotiate(peer) {
  if (peer.makingOffer || peer.pc.signalingState !== 'stable') return;
  peer.makingOffer = true;
  try {
    await peer.pc.setLocalDescription(await peer.pc.createOffer());
    bcast({ kind:'offer', from:PEER_ID, to:peer.id, sdp:peer.pc.localDescription });
  } finally { peer.makingOffer = false; }
}
async function handleOffer(p, peer) {
  if (!peer) peer = makePeer(p.from);
  const collision = peer.makingOffer || peer.pc.signalingState !== 'stable';
  if (collision && !isPolite(p.from)) return;  // impolite drops the incoming
  await peer.pc.setRemoteDescription(p.sdp);
  await flushIce(peer);
  if (localStream) {
    const senders = peer.pc.getSenders();
    localStream.getTracks().forEach(t => { if (!senders.some(s => s.track === t)) peer.pc.addTrack(t, localStream); });
  }
  await peer.pc.setLocalDescription(await peer.pc.createAnswer());
  bcast({ kind:'answer', from:PEER_ID, to:p.from, sdp:peer.pc.localDescription });
}
async function addIce(peer, candidate) {
  if (!peer.pc.remoteDescription?.type) { peer.pendingIce.push(candidate); return; }
  try { await peer.pc.addIceCandidate(candidate); } catch (e) { console.warn(e); }
}
async function flushIce(peer) {
  while (peer.pendingIce.length) try { await peer.pc.addIceCandidate(peer.pendingIce.shift()); } catch {}
}
function makePeer(peerId) {
  const pc = new RTCPeerConnection({ iceServers: [{ urls:'stun:stun.l.google.com:19302' }] });
  pc.onicecandidate = e => e.candidate && bcast({ kind:'ice', from:PEER_ID, to:peerId, candidate:e.candidate });
  pc.ontrack = e => {
    // ✅ ev.streams[0] - the sender's exact stream. Don't hand-roll.
    document.getElementById('remote-' + peerId).srcObject = e.streams[0];
  };
  pc.onnegotiationneeded = () => renegotiate(peers.get(peerId));
  const peer = { id:peerId, pc, pendingIce:[], makingOffer:false };
  peers.set(peerId, peer);
  return peer;
}
